argv:
set -eu
pr=$1; github=$2; expected_head=$3; expected_base=$4; expected_ref=$5; ticket=$6; repo=$7; base=$8; root=$9
emit_internal() {
  kind=$1
  KIND=$kind REPO=$repo GITHUB=$github PR=$pr TICKET=$ticket HEAD=$expected_head HEADREF=$expected_ref BASE=$base MERGE=${landed:-} ROOT=$root bun -e 'const p=process.env; const dbModule=await import(`file://${p.ROOT}/event-runtime/lib/db.mjs`); const chainModule=await import(`file://${p.ROOT}/event-runtime/lib/chain.mjs`); const db=dbModule.openDb(); const rows=db.query(`SELECT run_id FROM runs WHERE state = "RUNNING" AND json_extract(spec_json, "$.agent") = "merge-apply@2" AND json_extract(spec_json, "$.input.plan[0].pr") = ? AND json_extract(spec_json, "$.input.plan[0].headSha") = ?`).all(Number(p.PR),p.HEAD); if(rows.length!==1) throw new Error(`expected one running merge apply, found ${rows.length}`); const causationId=rows[0].run_id; const landed=p.KIND==="landed"; const eventId=landed?`merge-landed:${p.GITHUB}:${p.PR}:${p.MERGE}`:`merge-refresh:${p.REPO}:${p.PR}:${p.HEAD}`; const payload=landed?{repo:p.REPO,github:p.GITHUB,base:p.BASE,pr:Number(p.PR),ticket:p.TICKET,headSha:p.HEAD,headRef:p.HEADREF,mergeCommitSha:p.MERGE}:{repo:p.REPO,prNumbers:[Number(p.PR)]}; const outcome=chainModule.admitChainEvent(db,await import(`file://${p.ROOT}/event-runtime/lib/registry.mjs`).then(m=>m.loadRegistry()),{schemaVersion:"factory.event/v1",eventId,type:landed?"factory.merge-landed":"factory.merge.requested",subject:p.REPO,occurredAt:new Date().toISOString(),correlationId:eventId,causationId,payload}); db.close(); if(!outcome.admitted&&!outcome.duplicate) throw new Error(outcome.errors.join("; "));'
}
refresh() { emit_internal refresh; }
view=$(gh pr view "$pr" --repo "$github" --json state,isDraft,mergeable,headRefOid,headRefName,baseRefName,labels)
actual_head=$(printf '%s' "$view" | jq -r .headRefOid)
actual_base=$(gh api "repos/$github/git/ref/heads/$base" --jq .object.sha)
if [ "$actual_head" != "$expected_head" ] || [ "$actual_base" != "$expected_base" ]; then refresh; echo "stale reviewed SHA; fresh scan emitted" >&2; exit 0; fi
[ "$(printf '%s' "$view" | jq -r .state)" = OPEN ] || { echo "PR is not open" >&2; exit 1; }
[ "$(printf '%s' "$view" | jq -r .isDraft)" = false ] || { echo "PR is draft" >&2; exit 1; }
[ "$(printf '%s' "$view" | jq -r .mergeable)" = MERGEABLE ] || { refresh; echo "PR is not definitely mergeable" >&2; exit 0; }
[ "$(printf '%s' "$view" | jq -r .headRefName)" = "$expected_ref" ] || { refresh; echo "head branch moved" >&2; exit 0; }
[ "$(printf '%s' "$view" | jq -r .baseRefName)" = "$base" ] || { echo "base branch changed" >&2; exit 1; }
[ "$base" = develop ] || { echo "only develop is auto-mergeable" >&2; exit 1; }
! printf '%s' "$view" | jq -e '[.labels[].name|ascii_downcase] | any(. == "escalated" or . == "ai:escalated")' >/dev/null || { echo "GitHub escalation hold present" >&2; exit 1; }
linear=$(factory linear get "$ticket" --json) || { echo "Linear lookup failed" >&2; exit 1; }
printf '%s' "$linear" | jq -e 'type == "object" and (.state.name | type == "string" and length > 0) and (.labels.nodes | type == "array" and all(.[]; .name | type == "string" and length > 0))' >/dev/null || { echo "Linear lookup was empty or malformed" >&2; exit 1; }
linear_state=$(printf '%s' "$linear" | jq -r .state.name)
linear_labels=$(printf '%s' "$linear" | jq -r '.labels.nodes[].name')
[ "$linear_state" != Blocked ] || { echo "Linear Blocked hold present" >&2; exit 1; }
! printf '%s\n' "$linear_labels" | rg -qi '^(ai:escalated|type:security|.*security.*)$' || { echo "Linear escalation/security hold present" >&2; exit 1; }
required_status=0
required=$(gh pr checks "$pr" --repo "$github" --required --json name,bucket,state 2>&1) || required_status=$?
if [ "$required_status" -ne 0 ]; then
  if [ "$required_status" -eq 1 ] && [ "$required" = "no required checks reported on the '$expected_ref' branch" ]; then
    required='[]'
  else
    refresh
    printf 'GitHub required-context lookup failed: %s\n' "$required" >&2
    exit 0
  fi
fi
printf '%s' "$required" | jq -e 'type == "array" and all(.[]; (.name | type == "string" and length > 0)) and (([.[].name] | unique | length) == length)' >/dev/null || { refresh; echo "GitHub required contexts are malformed or ambiguous" >&2; exit 0; }
required_count=$(printf '%s' "$required" | jq length)
if [ "$required_status" -eq 0 ] && [ "$required_count" -eq 0 ]; then refresh; echo "status-zero required contexts are unexpectedly empty" >&2; exit 0; fi
if [ "$required_count" -gt 0 ]; then
  printf '%s' "$required" | jq -e 'all(.[]; .bucket == "pass" and .state == "SUCCESS")' >/dev/null || { refresh; echo "GitHub required CI is pending or not green" >&2; exit 0; }
else
  gate=$(ROOT=$root REPO=$repo bun -e 'const p=process.env; const m=await import(`file://${p.ROOT}/event-runtime/lib/repos.mjs`); const r=m.getRepo(m.loadRepos({root:p.ROOT}),p.REPO); if(!r.mergeCi)process.exit(2); process.stdout.write(JSON.stringify(r.mergeCi))') || { refresh; echo "required contexts are empty and merge_ci fallback is unavailable" >&2; exit 0; }
  workflow=$(printf '%s' "$gate" | jq -r .workflow)
  expected=$(printf '%s' "$gate" | jq -c .requiredChecks)
  runs=$(gh run list --repo "$github" --workflow "$workflow" --event pull_request --commit "$expected_head" --limit 20 --json databaseId,status,conclusion,headSha,workflowName)
  run_count=$(printf '%s' "$runs" | jq --arg workflow "$workflow" --arg sha "$expected_head" '[.[] | select(.workflowName == $workflow and .headSha == $sha)] | length')
  [ "$run_count" -eq 1 ] || { refresh; echo "configured pull-request workflow is missing or ambiguous at reviewed SHA" >&2; exit 0; }
  run_id=$(printf '%s' "$runs" | jq -r --arg workflow "$workflow" --arg sha "$expected_head" '.[] | select(.workflowName == $workflow and .headSha == $sha) | .databaseId')
  run_ok=$(printf '%s' "$runs" | jq -r --arg workflow "$workflow" --arg sha "$expected_head" '.[] | select(.workflowName == $workflow and .headSha == $sha) | (.status == "completed" and .conclusion == "success")')
  [ "$run_ok" = true ] || { refresh; echo "configured pull-request workflow is pending or not green" >&2; exit 0; }
  jobs=$(gh run view "$run_id" --repo "$github" --json jobs --jq .jobs)
  printf '%s' "$jobs" | jq -e --argjson expected "$expected" 'type == "array" and (. as $jobs | all($expected[]; . as $name | [$jobs[] | select(.name == $name)] | length == 1) and all($expected[]; . as $name | [$jobs[] | select(.name == $name)][0] | .status == "completed" and .conclusion == "success"))' >/dev/null || { refresh; echo "configured CI checks are missing, pending, red, or ambiguous" >&2; exit 0; }
fi
final_head=$(gh pr view "$pr" --repo "$github" --json headRefOid --jq .headRefOid)
final_base=$(gh api "repos/$github/git/ref/heads/$base" --jq .object.sha)
if [ "$final_head" != "$expected_head" ] || [ "$final_base" != "$expected_base" ]; then refresh; echo "SHA moved while rechecking CI; fresh scan emitted" >&2; exit 0; fi
gh pr merge "$pr" --repo "$github" --squash --match-head-commit "$expected_head"
landed=$(gh pr view "$pr" --repo "$github" --json state,mergeCommit --jq 'select(.state == "MERGED") | .mergeCommit.oid')
[ -n "$landed" ] || { echo "merge outcome uncertain" >&2; exit 1; }
emit_internal landed
